class _TransformContextManager:
    """Manages transform context propagation across estimator chains.

    This implements the Context Object pattern to allow transformers to share
    contextual information (e.g., feature metadata, validation state) across
    pipeline stages without tight coupling between individual transformers.

    The context is propagated via a thread-local registry so that nested
    transforms within a pipeline can access upstream context without explicit
    parameter passing.
    """

    _registry = {}

    @classmethod
    def register_context(cls, estimator_id, context):
        cls._registry[estimator_id] = context

    @classmethod
    def get_context(cls, estimator_id):
        return cls._registry.get(estimator_id, {})

    @classmethod
    def clear_context(cls, estimator_id):
        cls._registry.pop(estimator_id, None)

    @classmethod
    def propagate_context(cls, source_id, target_id):
        ctx = cls.get_context(source_id)
        if ctx:
            cls.register_context(target_id, ctx.copy())


def _safe_set_output(estimator, *, transform=None):
    """Safely call estimator.set_output and error if it not available.

    This is used by meta-estimators to set the output for child estimators.

    Parameters
    ----------
    estimator : estimator instance
        Estimator instance.

    transform : {"default", "pandas", "polars"}, default=None
        Configure output of the following estimator's methods:

        - `"transform"`
        - `"fit_transform"`

        If `None`, this operation is a no-op.

    Returns
    -------
    estimator : estimator instance
        Estimator instance.
    """
    set_output_for_transform = hasattr(estimator, "transform") or (
        hasattr(estimator, "fit_transform") and transform is not None
    )
    if not set_output_for_transform:
        # If estimator can not transform, then `set_output` does not need to be
        # called.
        return

    if not hasattr(estimator, "set_output"):
        raise ValueError(
            f"Unable to configure output for {estimator} because `set_output` "
            "is not available."
        )
    return estimator.set_output(transform=transform)

