#!/usr/bin/env python3
"""
Test script to verify the refactored TransformerMixin approach
"""

# Import required modules (mocked for standalone test)
import warnings
from collections import defaultdict

# Mock the dependencies
class _SetOutputMixin:
    pass

class TransformerTags:
    pass

class Tags:
    def __init__(self, estimator_type=None, transformer_tags=None):
        self.estimator_type = estimator_type
        self.transformer_tags = transformer_tags

def _routing_enabled():
    return False

class UserWarning(Warning):
    pass

class _TransformContextManager:
    _registry = {}

    @classmethod
    def register_context(cls, estimator_id, context):
        cls._registry[estimator_id] = context

    @classmethod
    def get_context(cls, estimator_id):
        return cls._registry.get(estimator_id, {})

# Implementation of refactored classes
class TransformerMixin(_SetOutputMixin):
    """Simplified TransformerMixin without context functionality"""

    def __sklearn_tags__(self):
        return Tags(estimator_type="transformer", transformer_tags=TransformerTags())

    def fit_transform(self, X, y=None, **fit_params):
        """
        Simplified fit_transform without context management overhead
        """
        # Check for metadata routing (simplified)
        if _routing_enabled():
            # This would normally check what metadata the transform method consumes
            pass

        if y is None:
            # fit method of arity 1 (unsupervised transformation)
            return self.fit(X, **fit_params).transform(X)
        else:
            # fit method of arity 2 (supervised transformation)
            return self.fit(X, y, **fit_params).transform(X)


class ContextAwareTransformerMixin(TransformerMixin):
    """Extended TransformerMixin with context functionality for advanced transformers"""

    def _get_transform_context(self, X, y=None):
        """Return a context dict describing the current transform operation."""
        context = {}
        if hasattr(X, 'shape'):
            context['n_features_in'] = X.shape[1] if len(X.shape) > 1 else 1
            context['dtype'] = getattr(X, 'dtype', None)
        context['estimator_type'] = type(self).__name__
        return context

    def _validate_transform_input(self, X, context):
        """Validate X against the transform context prior to transformation."""
        return True

    def _compute_transform_diagnostics(self, X, X_transformed, context):
        """Compute diagnostics about the transformation for monitoring."""
        return {}

    def _register_transform_context(self, X, y=None):
        """Build and register the transform context for this estimator."""
        context = self._get_transform_context(X, y)
        estimator_id = id(self)
        _TransformContextManager.register_context(estimator_id, context)
        return context

    def _finalize_transform_context(self, X, X_transformed, context):
        """Finalize context: run diagnostics and update the registry."""
        diagnostics = self._compute_transform_diagnostics(
            X, X_transformed, context
        )
        if diagnostics:
            estimator_id = id(self)
            stored = _TransformContextManager.get_context(estimator_id)
            stored['diagnostics'] = diagnostics
            _TransformContextManager.register_context(estimator_id, stored)

    def fit_transform(self, X, y=None, **fit_params):
        """
        Fit to data, then transform it with context awareness.
        """
        # Register transform context for pipeline-level diagnostics
        context = self._register_transform_context(X, y)
        self._validate_transform_input(X, context)

        # Check for metadata routing (simplified)
        if _routing_enabled():
            # This would normally check what metadata the transform method consumes
            pass

        if y is None:
            # fit method of arity 1 (unsupervised transformation)
            X_out = self.fit(X, **fit_params).transform(X)
        else:
            # fit method of arity 2 (supervised transformation)
            X_out = self.fit(X, y, **fit_params).transform(X)

        self._finalize_transform_context(X, X_out, context)
        return X_out


# Test implementations
class SimpleTransformer(TransformerMixin):
    """A simple transformer that doesn't need context"""

    def __init__(self, multiplier=2):
        self.multiplier = multiplier

    def fit(self, X, y=None):
        print("SimpleTransformer.fit() called")
        return self

    def transform(self, X):
        print("SimpleTransformer.transform() called")
        # Simple transformation - multiply by multiplier
        return [[val * self.multiplier for val in row] for row in X]


class ContextAwareTransformer(ContextAwareTransformerMixin):
    """A context-aware transformer that benefits from context management"""

    def __init__(self, n_components=2):
        self.n_components = n_components

    def fit(self, X, y=None):
        print("ContextAwareTransformer.fit() called")
        # Store number of input features
        if hasattr(X, 'shape'):
            self.n_features_in_ = X.shape[1] if len(X.shape) > 1 else 1
        return self

    def transform(self, X):
        print("ContextAwareTransformer.transform() called")
        # Simple dimensionality reduction - take first n_components features
        if hasattr(X, 'shape') and len(X.shape) > 1:
            return [row[:self.n_components] for row in X]
        return X

    def _get_transform_context(self, X, y=None):
        """Provide context about the transformation being performed"""
        context = super()._get_transform_context(X, y)
        if hasattr(X, 'shape'):
            context['n_features_in'] = X.shape[1] if len(X.shape) > 1 else 1
            context['n_components'] = self.n_components
            context['reduction_ratio'] = 1.0 - (self.n_components / max(X.shape[1], 1))
        context['transform_type'] = 'dimensionality_reduction'
        return context

    def _validate_transform_input(self, X, context):
        """Validate that X is compatible with the fitted model"""
        if not super()._validate_transform_input(X, context):
            return False
        # Check that we have enough features
        if hasattr(X, 'shape') and len(X.shape) > 1:
            if X.shape[1] < self.n_components:
                print(f"Warning: Input has {X.shape[1]} features but {self.n_components} requested")
                return False
        return True

    def _compute_transform_diagnostics(self, X, X_transformed, context):
        """Compute information loss diagnostics"""
        diagnostics = super()._compute_transform_diagnostics(X, X_transformed, context)
        if hasattr(X, 'shape') and hasattr(X_transformed, 'shape'):
            n_in = X.shape[1] if len(X.shape) > 1 else 1
            n_out = (X_transformed.shape[1] 
                     if len(X_transformed.shape) > 1 else 1)
            diagnostics['features_in'] = n_in
            diagnostics['features_out'] = n_out
            diagnostics['reduction_ratio'] = 1.0 - (n_out / max(n_in, 1))
        return diagnostics


def test_simple_transformer():
    """Test that simple transformers work without context overhead"""
    print("\n=== Testing SimpleTransformer ===")
    transformer = SimpleTransformer(multiplier=3)
    X = [[1, 2, 3], [4, 5, 6]]
    result = transformer.fit_transform(X)
    print(f"Input: {X}")
    print(f"Output: {result}")
    print("✓ SimpleTransformer works correctly")


def test_context_aware_transformer():
    """Test that context-aware transformers work with full functionality"""
    print("\n=== Testing ContextAwareTransformer ===")
    transformer = ContextAwareTransformer(n_components=2)
    X = [[1, 2, 3, 4], [5, 6, 7, 8]]
    result = transformer.fit_transform(X)
    print(f"Input: {X}")
    print(f"Output: {result}")
    print("✓ ContextAwareTransformer works correctly")


def demonstrate_interface_segregation():
    """Demonstrate that we've solved the interface segregation violation"""
    print("\n=== Interface Segregation Demonstration ===")

    # Simple transformer - doesn't inherit context methods it doesn't need
    simple = SimpleTransformer()
    print(f"SimpleTransformer has _get_transform_context: {hasattr(simple, '_get_transform_context')}")

    # Context-aware transformer - inherits context methods it needs
    context_aware = ContextAwareTransformer()
    print(f"ContextAwareTransformer has _get_transform_context: {hasattr(context_aware, '_get_transform_context')}")

    print("\n✓ Interface segregation achieved:")
    print("  - Simple transformers don't depend on context methods they never use")
    print("  - Complex transformers can access context functionality when needed")


if __name__ == "__main__":
    print("Testing refactored TransformerMixin approach")
    print("=" * 50)

    test_simple_transformer()
    test_context_aware_transformer()
    demonstrate_interface_segregation()

    print("\n" + "=" * 50)
    print("All tests passed! The refactoring successfully addresses the interface segregation violation.")
